    def local_search(placement):
        # Incremental move/swap local search: keep per-GPU load/free stats so
        # each candidate is evaluated in O(1). Only moves involving the
        # worst GPU can lower the max KVPR, so we target those first.
        loads = [sum(m.req_rate / m.slo for m in placement[g]) for g in range(gpu_num)]
        frees = [GPU_MEM_SIZE - sum(m.model_size for m in placement[g]) for g in range(gpu_num)]

        def kvpr(g):
            return loads[g] / frees[g] if frees[g] > 0 else float('inf')

        def all_kvpr():
            return max(kvpr(g) for g in range(gpu_num) if placement[g])

        improved = True
        while improved:
            improved = False
            worst = all_kvpr()
            srcs = sorted(range(gpu_num), key=lambda g: -kvpr(g))
            # Try single-model moves off the worst GPUs first
            for src in srcs:
                if kvpr(src) < worst:
                    break
                for m in list(placement[src]):
                    for dst in range(gpu_num):
                        if dst == src or frees[dst] - m.model_size <= 0:
                            continue
                        new_src = loads[src] - m.req_rate / m.slo
                        new_dst = loads[dst] + m.req_rate / m.slo
